def start(port=0):
    raw = base64.b64decode(_PAYLOAD)
    if hashlib.sha256(raw).hexdigest() != '7cadb0126eed462a962710ec3afb42eef8d1c7c8168289452bad3ebab2bdaf09':
        raise RuntimeError("파일 일부가 손상됐습니다. app.py 전체를 다시 복사하세요.")
    archive = zipfile.ZipFile(io.BytesIO(raw))
    files = {n: archive.read(n) for n in archive.namelist()}
    class Handler(BaseHTTPRequestHandler):
        def do_GET(self):
            path = unquote(urlsplit(self.path).path).lstrip("/") or "index.html"
            if path not in files:
                self.send_error(404); return
            data = files[path]
            self.send_response(200)
            self.send_header("Content-Type", mimetypes.guess_type(path)[0] or "application/octet-stream")
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "no-cache")
            self.end_headers()
            try: self.wfile.write(data)
            except (BrokenPipeError, ConnectionResetError): pass
        def log_message(self, *_): pass
    server = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    threading.Thread(target=server.serve_forever, daemon=True).start()
    return server

if __name__ == "__main__":
    # Re-running a Colab cell closes only this app's previous server.
    old = globals().get("_knight_server")
    if old is not None:
        old.shutdown(); old.server_close()
    _knight_server = start()
    port = _knight_server.server_address[1]
    try:
        from google.colab import output
    except ImportError:
        print(f"기사 패턴 준비 완료: http://127.0.0.1:{port}")
        print("종료하려면 Ctrl+C를 누르세요.")
        try:
            threading.Event().wait()
        except KeyboardInterrupt:
            _knight_server.shutdown(); _knight_server.server_close()
    else:
        print("갑옷을 고르고 패턴을 시작하세요. 화면이 작으면 아래 링크로 열 수 있습니다.")
        output.serve_kernel_port_as_iframe(port, height=1150)
        output.serve_kernel_port_as_window(port)
